/* Private follower pacing and demo presentation. No brother definitions, rewards or dialogue are rewritten. */
(function(){
 'use strict';
 const FROZEN=new Set(['G5','G3','G7','G7-SET','G6','G7-SERMON']);
 function frozen(){
  const a=window.RAAdventures?.active?.(),m=window.RAMinigames?.active?.();
  return FROZEN.has(a?.id)||FROZEN.has(m?.id)||String(a?.node||'').startsWith('BUILD3-G4')||String(a?.env||'').startsWith('G3-')||Object.values(a?.actors||{}).some(v=>['G1','LEGENDARY-MASK','legendary_masked_figure'].includes(typeof v==='string'?v:v?.id));
 }
 function normalGain(value){
  const n=Math.round(Number(value)||0);
  if(frozen()||window.RAState?.get?.().life.momentum.fameFired||n<=30)return n;
  return n<100?30:n<150?100:150;
 }
 const api={normalGain,frozen,milestones:{'carlos.checkin':10,m1:20,m3:30,m5:100,m8:150},breakthrough:44000,title:'Rich Alucard: Before The Fame demo.'};
 window.RALegendaryFollowers=api;
 RABuild3Stages.push(function(B){
  const P=RALegendary,A=RAAdventures,life=()=>RAState.get().life;
  const rawAdd=RALife.addFollowers;
  RALife.addFollowers=function(value,reason){
   if(frozen())return rawAdd(value,reason);
   const n=normalGain(value),tx=RAState.transaction(s=>{s.life.resources.followers=Math.max(0,(Number(s.life.resources.followers)||0)+n);return s.life.resources.followers;});
   if(tx.ok&&reason)RALife.remember({text:reason,type:'followers',quiet:true});return tx.ok?tx.value:life().resources.followers;
  };
  // System count spans only. Every surrounding word, character line, branch and source tuple stays exact.
  const captionEvents={LEGENDARY_CARLOS_CHECKIN:'carlos.checkin',NEW_OGA_M1:'m1',NEW_OGA_M3:'m3',NEW_OGA_M5:'m5',NEW_OGA_M8:'m8',LEGENDARY_RECOGNITION:'recognition.breakthrough'};
  const lines=A.linesFor;
  A.linesFor=function(node){
   const rows=lines(node),id=A.active()?.id,event=captionEvents[id];if(!event||frozen())return rows;
   const receipt=P.state().receipts[event],before=receipt?.followersBefore??life().resources.followers;
   // Old receipts have no follower snapshot: show the retained current count on both sides, never imply a replayed gain.
   const after=receipt?.followersAfter??(receipt?before:event==='recognition.breakthrough'?Math.max(before,44000):before+api.milestones[event]);
   const fmt=n=>new Intl.NumberFormat('en-US').format(n);
   return rows.map(row=>row?.[0]==null&&/Followers: [\d,.Kk]+ → [\d,.Kk]+(?: million)?\./.test(row[1])?[row[0],row[1].replace(/(Followers: )[\d,.Kk]+( → )[\d,.Kk]+(?: million)?(?=\.)/,(all,prefix,arrow)=>prefix+fmt(before)+arrow+fmt(after)),row[2]]:row);
  };
  // At the native wake node, award once even if the player interrupts before the final voice note.
  const enter=A.enter;
  A.enter=function(node){const result=enter(node);if(result?.def.id==='LEGENDARY_RECOGNITION')P.event('recognition.breakthrough');return result;};
  let overlay=null,timer=null;
  const remove=()=>{clearTimeout(timer);timer=null;overlay?.remove();overlay=null;document.body?.classList.remove('legendary-ending-active');};
  function showEnding(){
   if(typeof document.getElementById!=='function'||!P.state().demoEnding?.pending||A.active()||RAScenes.current()!=='bedroom'||frozen())return false;
   if(overlay?.isConnected)return true;
   const screen=document.querySelector('#screen');if(!screen)return false;document.body.classList.add('legendary-ending-active');
   let style=document.getElementById('legendary-demo-ending-style');if(!style){style=document.createElement('style');style.id='legendary-demo-ending-style';style.textContent='body.legendary-ending-active .rc3-cash{visibility:hidden}.legendary-demo-ending{position:absolute;inset:0;z-index:1000;display:flex;align-items:center;justify-content:center;box-sizing:border-box;padding:30px;background:#000;color:#f6efd9;opacity:0;transition:opacity .8s linear;pointer-events:auto}.legendary-demo-ending.visible{opacity:1}.legendary-demo-ending h1{margin:0;max-width:100%;text-align:center;font:clamp(12px,3.4cqw,20px)/2 var(--font-system);overflow-wrap:anywhere}.legendary-demo-ending h1{opacity:0;transition:opacity .6s linear .8s}.legendary-demo-ending.visible h1{opacity:1}@media(prefers-reduced-motion:reduce){.legendary-demo-ending,.legendary-demo-ending h1{transition:none}}';document.head.append(style);}
   overlay=document.createElement('section');overlay.className='legendary-demo-ending';overlay.setAttribute('aria-label',api.title);overlay.setAttribute('role','status');const title=document.createElement('h1');title.textContent=api.title;overlay.append(title);screen.append(overlay);
   requestAnimationFrame(()=>overlay?.classList.add('visible'));
   timer=setTimeout(()=>{if(overlay?.isConnected)RAState.transaction(s=>{const p=s.life.world.flags.legendaryPass;if(!p?.demoEnding?.pending)return false;p.demoEnding.seen=true;return true;});},1500);
   return true;
  }
  document.addEventListener('ra:scene',()=>{if(RAScenes.current()!=='bedroom')remove();else showEnding();});
  B.onComplete(r=>{if(r.id==='LEGENDARY_RECOGNITION')setTimeout(showEnding,0);});
  api.showEnding=showEnding;api.removeEnding=remove;
 });
})();

(function(){
 'use strict';
 // Additive bedroom staging only. Inert until the coordinator supplies the
 // exact accepted native sprite hash and its measured Presentation metadata.
 let selected=null,wrapped=null;
 const NATIVE={"src":"assets/sealed/player_feedback/kiki-seated-native-v2.png","sha256":"9140aa3eb0612c7e8493cb84ab54b7fc35a44c7d5d9d78fd6af2052c704f32aa","accepted":true,"metadata":{"width":80,"height":96,"sha256":"9140aa3eb0612c7e8493cb84ab54b7fc35a44c7d5d9d78fd6af2052c704f32aa","anchor":[40,88],"visible":[19,33,42,55],"support":{"y":88,"x1":33,"x2":51,"threshold":128},"face":[35,41,14,12],"faceSource":"artist-inspected-native","authority":"ACCEPTED_NATIVE_PLAYER_FEEDBACK","facing":"left"}};
 const SEAT={x:214,y:358},CAT={x:166,y:338};
 function ready(){
  const meta=selected&&window.RAPresentationAssets?.[selected.src];
  return !!(meta&&meta.sha256===selected.sha256&&meta.width===80&&meta.height===96&&
   meta.anchor?.[0]===40&&meta.anchor?.[1]===88&&meta.support?.y===88);
 }
 function configure(candidate){
  if(candidate==null){selected=null;return false;}
  if(candidate.accepted!==true||!/^assets\/.+\.png$/.test(candidate.src||'')||
   !/^[a-f0-9]{64}$/.test(candidate.sha256||''))throw new Error('ACCEPTED_NATIVE_KIKI_REQUIRED');
  selected={src:candidate.src,sha256:candidate.sha256};return ready();
 }
 function seated(spec){
  return {...(typeof spec==='object'?spec:{}),id:'kiki',state:'seated',
   src:selected.src,x:SEAT.x,y:SEAT.y,lineScale:1,flip:false};
 }
 function id(spec){return typeof spec==='string'?spec:spec?.id;}
 function companyPose(company){
  return ready()&&company?.kind==='woman'&&company.id==='kiki'?
   {src:selected.src,contact:[SEAT.x,SEAT.y]}:null;
 }
 function install(){
  window.RAPresentationAssets=window.RAPresentationAssets||{};
  window.RAPresentationAssets[NATIVE.src]=NATIVE.metadata;
  if(!selected)configure(NATIVE);
  const prior=window.RAWorldPresentation;
  if(!prior||prior===wrapped||typeof prior.actors!=='function')return;
  const actors=prior.actors,mount=prior.mount;wrapped=prior;
  prior.actors=function(env,cast){
   const resolved=actors.call(this,env,cast);
   if(env?.id!=='bedroom'||!ready()||!Object.values(resolved||{}).some(v=>id(v)==='kiki'))return resolved;
   return Object.fromEntries(Object.entries(resolved||{}).map(([slot,spec])=>{
    if(id(spec)==='kiki')return [slot,seated(spec)];
    if(id(spec)==='cat')return [slot,{...(typeof spec==='object'?spec:{}),id:'cat',x:CAT.x,y:CAT.y,lineScale:1,flip:false}];
    return [slot,spec];
   }));
  };
  prior.mount=function(root,scope,env,cast){
   const result=mount?.call(this,root,scope,env,cast);
   if(env?.id==='bedroom'&&ready())for(const el of root.querySelectorAll('[data-actor="kiki"]')){
    if(el.getAttribute('src')!==selected.src)continue;
    // A seated pose changes in place; never tween from standing percentages.
    el.style.transition='none';el.style.animation='none';
   }
   return result;
  };
 }
 window.RALegendaryBedroomVisuals={configure,install,companyPose,report:()=>({ready:ready(),selected:selected&&{...selected},seat:{...SEAT},catWithKiki:{...CAT}})};
 if(window.RABuild3Stages)window.RABuild3Stages.push(install);
})();

