   const drafted=global.RABuild3DraftedLines;if(drafted){const byKey=new Map(data.drafts.map(r=>[r.code+'\0'+r.key,r]));const rows=drafted.rows.map(r=>{const x=byKey.get(r.code+'\0'+r.key);return Object.freeze({...r,text:x?.replacementText??r.text,astraRecordId:x?.inventoryId});});global.RABuild3DraftedLines=Object.freeze({...drafted,rows:Object.freeze(rows)});}
